vector<vector<long long> > matmul(vector<vector<long long> > m1, vector<vector<long long> > m2, vector<vector<long long> > &m3){
    m3.clear();
    vector<vector<long long> > ans;
    REP(i,SZ(m1)){
        vector<long long> v;

        REP(j,SZ(m2[0])){
            v.PB(0);
        }
        ans.PB(v);
    }

    REP(r,SZ(m1)){
        REP(c,SZ(m2[0])){
            REP(k, SZ(m2)){
                ans[r][c] += m1[r][k]*m2[k][c];
                ans[r][c]%=MOD;
            }
        }
    }

    REP(i,SZ(m1)){
        vector<long long> cur;
        REP(j,SZ(m2[0])){
            cur.PB(ans[i][j]);
        }
        m3.PB(cur);
    }
    return m3;


}
vector<ll> mymul(vector<ll> vec, vector<vector<ll> > mat, vector<ll> &ret){
    vector<ll> res;
    REP(i,SZ(vec)){
        ll sum = 0;
        for(int co = 0; co < SZ(mat); co++){
            sum += vec[co]*mat[co][i];
            sum%=MOD;
        }
        res.PB(sum);
    }
    ret.clear();
    REP(i,SZ(res)) ret.PB(res[i]);
    return ret;
}
