vector<vector<long long> > matexp(vector<vector<long long> > matr, long long n){
    vector<vector<long long> > ans;
    REP(i,SZ(matr)){
        vector<long long> v;
        REP(j,SZ(matr[0])){
            v.PB((i==j));
        }
        ans.PB(v);
    }
    long long t = n;

    while(t>0){

        if(t%2==0){
            matmul(matr,matr,matr);
            t/=2;
        }
        else{
            matmul(ans,matr,ans);
            t--;
        }
    }

    return ans;
}

